#include "sblr_atomic_cas_runtime.hpp"
#include "core/hash/hash_digest.hpp"
#include <algorithm>
#include <cstring>
namespace scratchbird::engine::sblr{namespace{void p(std::vector<uint8_t>&o,uint64_t v,size_t n){for(size_t i=0;i<n;++i)o.push_back((v>>(8*i))&255);}uint64_t g(const uint8_t*b,size_t n){uint64_t v=0;for(size_t i=0;i<n;++i)v|=uint64_t(b[i])<<(8*i);return v;}template<class T>bool nz(const T&x){return std::any_of(x.begin(),x.end(),[](auto v){return v;});}std::vector<uint8_t>hd(const char*m,size_t n){std::vector<uint8_t>o(m,m+4);p(o,1,2);p(o,n,2);p(o,n,4);p(o,0,4);return o;}bool vh(const uint8_t*b,size_t n,const char*m,size_t x){return n==x&&std::equal(b,b+4,m)&&g(b+4,2)==1&&g(b+6,2)==x&&g(b+8,4)==x&&std::all_of(b+12,b+16,[](auto v){return !v;});}AtomicCasSha sh(const char*d,const uint8_t*b,size_t n){std::vector<uint8_t>x(d,d+std::strlen(d));x.insert(x.end(),b,b+n);return scratchbird::core::hash::ComputeSha256Digest(x).digest;}}
std::vector<uint8_t>EncodeSblrAtomicCasRequestV1(const SblrAtomicCasRequestV1&v){if(!nz(v.receipt)||!v.occurrence||!v.cas_occurrence)return{};auto o=hd("CASQ",64);o.insert(o.end(),v.receipt.begin(),v.receipt.end());p(o,v.occurrence,8);p(o,v.cas_occurrence,4);o.insert(o.end(),20,0);return o;}bool DecodeSblrAtomicCasRequestV1(const uint8_t*b,size_t n,SblrAtomicCasRequestV1*out,std::string*d){if(!out||!vh(b,n,"CASQ",64)||std::any_of(b+44,b+64,[](auto v){return v;})){if(d)*d="CASQ invalid";return false;}SblrAtomicCasRequestV1 v;std::copy_n(b+16,16,v.receipt.begin());v.occurrence=g(b+32,8);v.cas_occurrence=g(b+40,4);if(EncodeSblrAtomicCasRequestV1(v).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrAtomicCasDescriptorV1(const SblrAtomicCasDescriptorV1&v,bool op){if(!nz(v.canonical_body)||!v.availability_generation)return{};auto o=hd(op?"CASO":"CASD",488);o.insert(o.end(),v.canonical_body.begin(),v.canonical_body.end());auto e=sh("ScratchBird.SblrAtomicCasDescriptor.V1",o.data()+16,432);if(nz(v.evidence)&&v.evidence!=e)return{};o.insert(o.end(),e.begin(),e.end());p(o,v.availability_generation,8);return o;}bool DecodeSblrAtomicCasDescriptorV1(const uint8_t*b,size_t n,SblrAtomicCasDescriptorV1*out,std::string*d,bool op){if(!out||!vh(b,n,op?"CASO":"CASD",488)){if(d)*d="CAS descriptor invalid";return false;}SblrAtomicCasDescriptorV1 v;std::copy_n(b+16,432,v.canonical_body.begin());std::copy_n(b+448,32,v.evidence.begin());v.availability_generation=g(b+480,8);if(EncodeSblrAtomicCasDescriptorV1(v,op).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrAtomicCasResultV1(const SblrAtomicCasResultV1&v){if(!nz(v.canonical_body)||!v.availability_generation)return{};auto o=hd("CASR",224);o.insert(o.end(),v.canonical_body.begin(),v.canonical_body.end());auto e=sh("ScratchBird.SblrAtomicCasResult.V1",o.data()+16,168);if(nz(v.evidence)&&v.evidence!=e)return{};o.insert(o.end(),e.begin(),e.end());p(o,v.availability_generation,8);return o;}bool DecodeSblrAtomicCasResultV1(const uint8_t*b,size_t n,SblrAtomicCasResultV1*out,std::string*d){if(!out||!vh(b,n,"CASR",224)){if(d)*d="CASR invalid";return false;}SblrAtomicCasResultV1 v;std::copy_n(b+16,168,v.canonical_body.begin());std::copy_n(b+184,32,v.evidence.begin());v.availability_generation=g(b+216,8);if(EncodeSblrAtomicCasResultV1(v).empty())return false;*out=v;return true;}}
